/*
 * ---------------------------------------------------------------------------
 * Written by hand, not generated (ADR-0025, ADR-0026, ADR-0027): sessions,
 * sign-in identities, invitations, share links and the desktop handoff, added
 * after the rest of this file was generated. Merged into
 * `paths` above by declaration merging; checked by server/tests/api.rs.
 * ---------------------------------------------------------------------------
 */

type NoParams = { query?: never; header?: never; path?: never; cookie?: never };
type PathParams<P> = { query?: never; header?: never; path: P; cookie?: never };
type Json<T> = { headers: { [name: string]: unknown }; content: { "application/json": T } };
type Empty = { headers: { [name: string]: unknown }; content?: never };
type Body<T> = { content: { "application/json": T } };
type Read<Params, Res> = { parameters: Params; requestBody?: never; responses: Res };
type Op<Params, Req, Res> = { parameters: Params; requestBody: Req; responses: Res };

export interface SessionView {
    id: string;
    kind: "browser" | "device";
    label?: string | null;
    createdAt: string;
    lastSeenAt: string;
    expiresAt: string;
    current: boolean;
}

export interface Identities {
    hasPassword: boolean;
    identities: { provider: string; name: string; email?: string | null; createdAt: string }[];
}

export interface Invitation {
    id: string;
    purpose: "join" | "reset";
    admin: boolean;
    note?: string | null;
    /** reset: whose password. */
    username?: string | null;
    createdAt: string;
    expiresAt: string;
    /** Only in the answer that created it: `/invite#{token}`. */
    link?: string;
}

export interface InvitationInfo {
    purpose: "join" | "reset";
    admin: boolean;
    note?: string | null;
    username?: string | null;
    expiresAt: string;
    passwordEnabled: boolean;
}

export interface ShareLink {
    id: string;
    canvasId: string;
    label?: string | null;
    createdBy?: string | null;
    createdByName?: string | null;
    createdAt: string;
    expiresAt?: string | null;
    hasPassphrase: boolean;
    lastUsedAt?: string | null;
    /** Only in the answer that created it: `/s#{token}`. */
    link?: string;
}

export interface SharedSession {
    member: boolean;
    boardId: string;
    title?: string;
    sharedBy?: string | null;
}

export interface SharedBoard extends Omit<components["schemas"]["BoardSnapshot"], never> {
    id: string;
    title: string;
    sharedBy?: string | null;
    expiresAt?: string | null;
}

export interface paths {
    "/api/sessions": {
        parameters: NoParams;
        /** My sessions, browsers and devices, most recently used first */
        get: Read<NoParams, { 200: Json<SessionView[]> }>;
        /** Sign out every session of mine except this one */
        delete: Read<NoParams, { 204: Empty }>;
    };
    "/api/sessions/{id}": {
        parameters: NoParams;
        delete: Read<PathParams<{ id: string }>, { 204: Empty }>;
    };
    "/api/accounts/me/identities": {
        parameters: NoParams;
        get: Read<NoParams, { 200: Json<Identities> }>;
    };
    "/api/accounts/me/identities/{provider}": {
        parameters: NoParams;
        /** Refused (409) when it would leave the account with no way in */
        delete: Read<PathParams<{ provider: string }>, { 204: Empty }>;
    };
    "/api/invitations": {
        parameters: NoParams;
        get: Read<NoParams, { 200: Json<Invitation[]> }>;
        post: Op<
            NoParams,
            Body<{ purpose?: "join" | "reset"; admin?: boolean; note?: string; userId?: string }>,
            { 201: Json<Invitation> }
        >;
    };
    "/api/invitations/{id}": {
        parameters: NoParams;
        delete: Read<PathParams<{ id: string }>, { 204: Empty }>;
    };
    "/api/invitations/inspect": {
        parameters: NoParams;
        post: Op<NoParams, Body<{ token: string }>, { 200: Json<InvitationInfo> }>;
    };
    "/api/invitations/redeem": {
        parameters: NoParams;
        /** join: 201 with the new account, signed in. reset: 204 */
        post: Op<
            NoParams,
            Body<{ token: string; password: string; username?: string; displayName?: string }>,
            { 201: Json<components["schemas"]["AppUser"]>; 204: Empty }
        >;
    };
    "/api/invitations/redeem/{provider}": {
        parameters: NoParams;
        /** Where to send the browser to join through a provider */
        post: Op<PathParams<{ provider: string }>, Body<{ token: string }>, { 200: Json<{ redirect: string }> }>;
    };
    "/api/boards/{id}/shares": {
        parameters: NoParams;
        get: Read<PathParams<{ id: string }>, { 200: Json<ShareLink[]> }>;
        post: Op<
            PathParams<{ id: string }>,
            Body<{ label?: string; expiresInDays?: 1 | 7 | 30 | null; passphrase?: string }>,
            { 201: Json<ShareLink> }
        >;
    };
    "/api/shares": {
        parameters: NoParams;
        get: Read<NoParams, { 200: Json<ShareLink[]> }>;
    };
    "/api/shares/{id}": {
        parameters: NoParams;
        delete: Read<PathParams<{ id: string }>, { 204: Empty }>;
        patch: Op<PathParams<{ id: string }>, Body<{ passphrase: string | null }>, { 200: Json<ShareLink> }>;
    };
    "/api/shared/session": {
        parameters: NoParams;
        post: Op<NoParams, Body<{ token: string; passphrase?: string }>, { 200: Json<SharedSession> }>;
    };
    "/api/shared/board": {
        parameters: NoParams;
        get: Read<NoParams, { 200: Json<SharedBoard> }>;
    };
    "/api/device/authorize": {
        parameters: NoParams;
        post: Op<
            NoParams,
            Body<{ port: number; challenge: string; state: string; label?: string }>,
            { 200: Json<{ redirect: string }> }
        >;
    };
    "/api/device-tokens": {
        parameters: NoParams;
        post: Op<
            NoParams,
            Body<{ code: string; verifier: string }>,
            { 201: Json<{ token: string; user: components["schemas"]["AppUser"] }> }
        >;
    };
}
